# ============================================================
# ШАХМАТНАЯ ИГРА
# ============================================================

class ChessGame:

    def __init__(
        self,
        player_color=chess.WHITE,
        depth=ENGINE_DEPTH,
        opening="none"
    ):

        self.player_color = player_color
        self.depth = depth

        if opening not in OPENING_BOOK:
            opening = "none"

        self.opening = opening

        self.opening_book = OPENING_BOOK.get(
            opening,
            {}
        )

        self.opening_active = (
            opening != "none"
        )

        self.board = chess.Board()

        self.move_history = []

        self.resigned_by_player = False

        self.engine = chess.engine.SimpleEngine.popen_uci(
            ENGINE_PATH
        )


    # ========================================================
    # СБРОС ПАРТИИ
    # ========================================================

    def reset(self):

        self.board = chess.Board()

        self.move_history = []

        self.resigned_by_player = False

        self.opening_book = OPENING_BOOK.get(
            self.opening,
            {}
        )

        self.opening_active = (
            self.opening != "none"
        )


    # ========================================================
    # ЗАКРЫТИЕ STOCKFISH
    # ========================================================

    def close(self):

        if self.engine:

            try:
                self.engine.quit()

            except Exception:
                pass

            self.engine = None


    # ========================================================
    # FEN
    # ========================================================

    def get_fen(self):

        return self.board.fen()


    # ========================================================
    # PGN
    # ========================================================

    def get_pgn(self):

        game = chess.pgn.Game()

        game.headers["Event"] = "Chess Trainer"

        if self.player_color == chess.WHITE:

            game.headers["White"] = "Player"
            game.headers["Black"] = "Computer"

        else:

            game.headers["White"] = "Computer"
            game.headers["Black"] = "Player"

        game.headers["Result"] = self.get_result()

        node = game

        for move in self.board.move_stack:

            node = node.add_variation(move)

        return str(game)


    # ========================================================
    # РЕЗУЛЬТАТ ПАРТИИ
    # ========================================================

    def get_result(self):

        if self.resigned_by_player:

            if self.player_color == chess.WHITE:
                return "0-1"

            return "1-0"

        if self.board.is_checkmate():

            if self.board.turn == chess.WHITE:
                return "0-1"

            return "1-0"

        if self.board.is_stalemate():

            return "1/2-1/2"

        if self.board.is_insufficient_material():

            return "1/2-1/2"

        if self.board.is_fifty_moves():

            return "1/2-1/2"

        if self.board.is_fivefold_repetition():

            return "1/2-1/2"

        if self.board.is_game_over(
            claim_draw=True
        ):

            return self.board.result(
                claim_draw=True
            )

        return "*"


    # ========================================================
    # ЛЕГАЛЬНЫЕ ХОДЫ
    # ========================================================

    def get_legal_moves(self):

        return [
            move.uci()
            for move in self.board.legal_moves
        ]


    # ========================================================
    # ЧЕЙ ХОД
    # ========================================================

    def is_player_turn(self):

        return (
            self.board.turn == self.player_color
        )


    # ========================================================
    # КОНЕЦ ПАРТИИ
    # ========================================================

    def is_game_over(self):

        if self.resigned_by_player:
            return True

        return self.board.is_game_over()


    # ========================================================
    # СТАТУС
    # ========================================================

    def get_status(self):

        if self.resigned_by_player:

            return "Вы сдались"

        if self.board.is_checkmate():

            if self.board.turn == self.player_color:
                return "Вы проиграли"

            return "Вы победили"

        if self.board.is_stalemate():

            return "Пат"

        if self.board.is_insufficient_material():

            return "Ничья: недостаточно материала"

        if self.board.is_fifty_moves():

            return "Ничья: правило 50 ходов"

        if self.board.is_repetition():

            return "Ничья: троекратное повторение"

        if self.board.is_game_over():

            return "Партия закончена"

        return "Партия продолжается"


    # ========================================================
    # ПОЛУЧЕНИЕ ХОДА ИЗ ДЕБЮТНОГО ДЕРЕВА
    # ========================================================
    #
    # ВАЖНЫЙ МОМЕНТ:
    #
    # Мы НЕ полагаемся только на opening_active.
    #
    # Если точная последовательность ходов существует
    # в OPENING_BOOK, компьютер использует её.
    #
    # Это предотвращает ситуацию:
    #
    # 1.e4 e6
    # 2.d4 d5
    # 3.Nd2
    #
    # когда вместо подготовленного Nf6 внезапно
    # включается Stockfish и выбирает c5.
    #
    # ========================================================

    def _get_opening_move(self):

        print("=== GET OPENING MOVE ===")
        print("OPENING:", self.opening)
        print("HISTORY:", tuple(self.move_history))
        print(
            "EXPECTED:",
            self.opening_book.get(
                tuple(self.move_history)
            )
        )

        if self.opening == "none":

            return None

        history = tuple(
            self.move_history
        )

        possible_moves = self.opening_book.get(
            history
        )

        # В этой точной позиции подготовленной
        # ветки нет.
        if not possible_moves:

            self.opening_active = False

            return None

        expected_uci = possible_moves[0]

        try:

            move = chess.Move.from_uci(
                expected_uci
            )

        except ValueError:

            self.opening_active = False

            return None

        # Защита от ошибки в дебютной книге.
        if move not in self.board.legal_moves:

            self.opening_active = False

            return None

        # Если точная ветка существует,
        # считаем дебют снова активным.
        self.opening_active = True

        return move


    # ========================================================
    # ПРОВЕРКА ХОДА ИГРОКА
    # ОТНОСИТЕЛЬНО ДЕБЮТНОГО ДЕРЕВА
    # ========================================================

    def _check_player_opening_move(
        self,
        move
    ):

        if self.opening == "none":

            self.opening_active = False

            return

        history = tuple(
            self.move_history
        )

        print("=== OPENING DEBUG ===")
        print("HISTORY:", history)
        print("EXPECTED:", self.opening_book.get(history))

        possible_moves = self.opening_book.get(
            history
        )

        # В этой позиции подготовленной ветки нет.
        if not possible_moves:

            self.opening_active = False

            return

        played_uci = move.uci()

        # Игрок выбрал одну из подготовленных веток.
        if played_uci in possible_moves:

            self.opening_active = True

            return

        # Игрок вышел из подготовленного дерева.
        # Дальше Stockfish.
        self.opening_active = False


    # ========================================================
    # ЛУЧШИЙ ХОД STOCKFISH
    # ========================================================

    def get_best_move(self):

        if self.engine is None:

            return None

        result = self.engine.analyse(
            self.board,
            chess.engine.Limit(
                depth=self.depth
            )
        )

        return result["pv"][0]


    # ========================================================
    # ПОДГОТОВКА ХОДА ИГРОКА
    # БЕЗ ОЖИДАНИЯ STOCKFISH
    # ========================================================

    def prepare_player_move(
        self,
        uci_move
    ):

        if self.board.turn != self.player_color:

            return {
                "success": False,
                "error": "Сейчас ход компьютера."
            }

        try:

            move = chess.Move.from_uci(
                uci_move
            )

        except ValueError:

            return {
                "success": False,
                "error": "Некорректный ход."
            }

        if move not in self.board.legal_moves:

            return {
                "success": False,
                "error": "Так сходить нельзя."
            }

        board_before = self.board.copy()

        # Проверяем ветку ДО добавления хода
        # в историю.
        self._check_player_opening_move(
            move
        )

        san = self.board.san(
            move
        )

        self.board.push(
            move
        )

        self.move_history.append(
            move.uci()
        )

        return {

            "success": True,

            "move":
                move.uci(),

            "played_move":
                move.uci(),

            "san":
                san,

            "board_before":
                board_before,

            "fen":
                self.get_fen(),

            "legal_moves":
                self.get_legal_moves(),

            "player_turn":
                self.is_player_turn(),

            "game_over":
                self.is_game_over(),

            "status":
                self.get_status(),
        }


    # ========================================================
    # АНАЛИЗ ХОДА ИГРОКА
    # ========================================================

    def analyze_player_move(
        self,
        board_before
    ):

        if self.engine is None:

            return {
                "best_move": None,
                "best_san": None,
                "is_best": False,
            }

        result = self.engine.analyse(
            board_before,
            chess.engine.Limit(
                depth=self.depth
            )
        )

        best_move = result["pv"][0]

        best_san = board_before.san(
            best_move
        )

        return {

            "best_move":
                best_move.uci(),

            "best_san":
                best_san,
        }


    # ========================================================
    # ХОД ИГРОКА
    # ========================================================

    def make_player_move(
        self,
        uci_move
    ):

        if self.resigned_by_player:

            return {
                "success": False,
                "error": "Партия уже закончена."
            }

        if self.board.turn != self.player_color:

            return {
                "success": False,
                "error": "Сейчас ход компьютера."
            }

        try:

            move = chess.Move.from_uci(
                uci_move
            )

        except ValueError:

            return {
                "success": False,
                "error": "Некорректный ход."
            }

        if move not in self.board.legal_moves:

            return {
                "success": False,
                "error": "Так сходить нельзя."
            }

        # Проверяем ветку ДО push.
        self._check_player_opening_move(
            move
        )

        san = self.board.san(
            move
        )

        self.board.push(
            move
        )

        self.move_history.append(
            move.uci()
        )

        return {

            "success": True,

            "move":
                move.uci(),

            "played_move":
                move.uci(),

            "san":
                san,

            "best_move":
                None,

            "fen":
                self.get_fen(),

            "legal_moves":
                self.get_legal_moves(),

            "player_turn":
                self.is_player_turn(),

            "game_over":
                self.is_game_over(),

            "status":
                self.get_status(),
        }


    # ========================================================
    # ХОД КОМПЬЮТЕРА
    # ========================================================

    def make_computer_move(self):

        if self.board.turn == self.player_color:

            return {
                "success": False,
                "error": "Сейчас ход игрока."
            }

        if self.is_game_over():

            return {
                "success": False,
                "error": "Партия уже закончена."
            }

        # ----------------------------------------------------
        # СНАЧАЛА ИЩЕМ ТОЧНУЮ ПОЗИЦИЮ В ДЕБЮТНОМ ДЕРЕВЕ
        # ----------------------------------------------------

        move = self._get_opening_move()

        opening_move = False

        if move is not None:

            opening_move = True

        # ----------------------------------------------------
        # ЕСЛИ ТОЧНОЙ ВЕТКИ НЕТ — STOCKFISH
        # ----------------------------------------------------

        if move is None:

            move = self.get_best_move()

            if move is None:

                return {
                    "success": False,
                    "error": "Stockfish не вернул ход."
                }

        # ----------------------------------------------------
        # SAN ДО PUSH
        # ----------------------------------------------------

        san = self.board.san(
            move
        )

        # ----------------------------------------------------
        # ДЕЛАЕМ ХОД
        # ----------------------------------------------------

        self.board.push(
            move
        )

        self.move_history.append(
            move.uci()
        )

        return {

            "success": True,

            "move":
                move.uci(),

            "san":
                san,

            "opening_move":
                opening_move,

            "opening":
                self.opening,

            "opening_active":
                self.opening_active,

            "fen":
                self.get_fen(),

            "legal_moves":
                self.get_legal_moves(),

            "player_turn":
                self.is_player_turn(),

            "game_over":
                self.is_game_over(),

            "status":
                self.get_status(),
        }

    # ============================================================
    # ПРОВЕРКА OPENING_BOOK НА НЕЛЕГАЛЬНЫЕ ХОДЫ
    # ============================================================

    def check_opening_book(book):
        import chess

        errors = []
        checked = 0

        for opening_name, opening_tree in book.items():

            print()
            print("=" * 70)
            print(f"ПРОВЕРКА ДЕБЮТА: {opening_name}")
            print("=" * 70)

            for move_sequence, responses in opening_tree.items():

                board = chess.Board()

                # Восстанавливаем позицию по ключу
                try:
                    for uci_move in move_sequence:
                        board.push_uci(uci_move)
                except Exception as e:
                    errors.append({
                        "opening": opening_name,
                        "sequence": move_sequence,
                        "move": uci_move,
                        "type": "ОШИБКА В КЛЮЧЕ",
                        "error": str(e),
                    })
                    continue

                # Проверяем все ответы из списка
                for response in responses:

                    checked += 1

                    try:
                        board.push_uci(response)

                    except Exception as e:
                        errors.append({
                            "opening": opening_name,
                            "sequence": move_sequence,
                            "move": response,
                            "type": "НЕЛЕГАЛЬНЫЙ ХОД",
                            "error": str(e),
                        })

                        print()
                        print("❌ НАЙДЕНА ОШИБКА")
                        print(f"Дебют: {opening_name}")
                        print(f"Позиция: {move_sequence}")
                        print(f"Ход:     {response}")
                        print(f"Ошибка:  {e}")

        print()
        print("=" * 70)
        print("ИТОГ ПРОВЕРКИ")
        print("=" * 70)

        print(f"Проверено ходов: {checked}")
        print(f"Ошибок:         {len(errors)}")

        if not errors:
            print()
            print("✅ ВСЕ ХОДЫ OPENING_BOOK ЛЕГАЛЬНЫ")
        else:
            print()
            print("❌ НАЙДЕНЫ ОШИБКИ:")

            for number, error in enumerate(errors, 1):
                print()
                print(f"{number}. {error['type']}")
                print(f"   Дебют:   {error['opening']}")
                print(f"   Позиция: {error['sequence']}")
                print(f"   Ход:     {error['move']}")
                print(f"   Ошибка:  {error['error']}")

        return errors

    def check_french_structure(book):
        """
        Проверка структуры французского OPENING_BOOK.

        OPENING_BOOK устроен так:

            position_tuple: [allowed_next_moves]

        Например:

            (
                "e2e4",
                "e7e6",
                "d2d4",
            ): [
                "d7d5"
            ]

        Следующие варианты могут начинаться уже отдельными KEY:

            (
                "e2e4",
                "e7e6",
                "d2d4",
                "d7d5",
                "b1c3",
            )

        Поэтому нельзя требовать, чтобы каждая промежуточная
        позиция обязательно была отдельным KEY.
        """

        print()
        print("=" * 70)
        print("ПРОВЕРКА СТРУКТУРЫ ФРАНЦУЗСКОЙ ЗАЩИТЫ")
        print("=" * 70)

        if "french" not in book:
            print("❌ В OPENING_BOOK нет раздела 'french'")
            return False

        tree = book["french"]

        errors = []

        # ============================================================
        # Эталонное начало
        # ============================================================

        french_prefix = (
            "e2e4",
            "e7e6",
            "d2d4",
            "d7d5",
        )

        # ============================================================
        # 1. Проверяем начало
        # ============================================================

        if () not in tree:
            errors.append("❌ Нет корня ()")
        elif "e2e4" not in tree[()]:
            errors.append("❌ Из корня отсутствует 1.e4")

        pos1 = ("e2e4",)

        if pos1 not in tree:
            errors.append("❌ Нет позиции после 1.e4")
        elif "e7e6" not in tree[pos1]:
            errors.append("❌ После 1.e4 отсутствует 1...e6")

        pos2 = (
            "e2e4",
            "e7e6",
        )

        if pos2 not in tree:
            errors.append("❌ Нет позиции после 1...e6")
        elif "d2d4" not in tree[pos2]:
            errors.append("❌ После 1...e6 отсутствует 2.d4")

        pos3 = (
            "e2e4",
            "e7e6",
            "d2d4",
        )

        if pos3 not in tree:
            errors.append("❌ Нет позиции после 2.d4")
        elif "d7d5" not in tree[pos3]:
            errors.append("❌ После 2.d4 отсутствует 2...d5")

        # ============================================================
        # 2. Находим ВСЕ ключи, которые действительно начинаются
        #    с французского начала
        # ============================================================

        french_keys = []

        for key in tree:

            if len(key) >= 4:

                if tuple(key[:4]) == french_prefix:

                    french_keys.append(key)

        # ============================================================
        # 3. Находим основные варианты после 2...d5
        #
        # Ищем ключи:
        #
        # 1.e4 e6 2.d4 d5 + один ход белых
        #
        # то есть длиной 5.
        # ============================================================

        main_branches = []

        for key in french_keys:

            if len(key) == 5:

                main_branches.append(key[4])

        print()
        print("ОСНОВНЫЕ ВЕТВИ ПОСЛЕ 2...d5:")

        if main_branches:

            for move in sorted(set(main_branches)):

                print(f"   • {move}")

        else:

            print("   ⚠️ Не найдены")

        # ============================================================
        # 4. Находим реальные конечные позиции
        #
        # Ключ считается продолжением, если существует другой KEY,
        # который начинается с него и содержит следующий ход.
        #
        # Важно:
        # сам KEY может иметь продолжения в другом KEY.
        # ============================================================

        terminal_keys = []

        for key in french_keys:

            has_child = False

            for other_key in french_keys:

                if len(other_key) <= len(key):
                    continue

                if tuple(other_key[:len(key)]) == key:

                    has_child = True
                    break

            if not has_child:

                # Но если у самого key есть ответы,
                # они образуют следующие позиции.
                #
                # Поэтому проверяем и VALUE.

                responses = tree.get(key, [])

                if responses:

                    for move in responses:

                        next_position = key + (move,)

                        # Если следующая позиция существует
                        # как KEY — это не конец.
                        if next_position in tree:

                            continue

                        # Если её нет как KEY — это реальный лист.
                        terminal_keys.append(next_position)

                else:

                    terminal_keys.append(key)

        # ============================================================
        # 5. Убираем дубликаты
        # ============================================================

        terminal_keys = sorted(
            set(terminal_keys),
            key=lambda x: (len(x), x)
        )

        # ============================================================
        # 6. Разделяем ветки по длине
        #
        # 20 полуходов = 10...
        # ============================================================

        complete_branches = []
        incomplete_branches = []

        for branch in terminal_keys:

            if len(branch) == 20:

                complete_branches.append(branch)

            elif len(branch) < 20:

                incomplete_branches.append(branch)

            else:

                errors.append(
                    "❌ Ветка длиннее 10...:\n"
                    f"   {branch}"
                )

        # ============================================================
        # 7. Вывод статистики
        # ============================================================

        print()
        print(
            f"Реальных конечных веток: {len(terminal_keys)}"
        )

        print(
            f"Полностью до 10...:       {len(complete_branches)}"
        )

        print(
            f"Оборвано раньше:          {len(incomplete_branches)}"
        )

        # ============================================================
        # 8. Готовые ветки
        # ============================================================

        if complete_branches:

            print()
            print("=" * 70)
            print("✅ ГОТОВЫЕ ВЕТКИ ДО 10...")
            print("=" * 70)

            for number, branch in enumerate(
                complete_branches,
                start=1
            ):

                print(
                    f"{number:2d}. {branch}"
                )

        # ============================================================
        # 9. Незавершённые ветки
        # ============================================================

        if incomplete_branches:

            print()
            print("=" * 70)
            print("⚠️ РЕАЛЬНО НЕЗАВЕРШЁННЫЕ ВЕТКИ")
            print("=" * 70)

            for number, branch in enumerate(
                incomplete_branches,
                start=1
            ):

                print(
                    f"{number:2d}. "
                    f"{len(branch):2d} полуходов: "
                    f"{branch}"
                )

        # ============================================================
        # 10. Ошибки
        # ============================================================

        if errors:

            print()
            print("=" * 70)
            print("❌ ОШИБКИ СТРУКТУРЫ")
            print("=" * 70)

            for error in errors:

                print(error)

        # ============================================================
        # 11. Итог
        # ============================================================

        print()
        print("=" * 70)

        if errors:

            print("❌ ПРОВЕРКА СТРУКТУРЫ НЕ ПРОЙДЕНА")

            print("=" * 70)

            return False

        if incomplete_branches:

            print(
                "⚠️ СТРУКТУРА КОРРЕКТНА, "
                "НО ЕСТЬ НЕЗАВЕРШЁННЫЕ ВЕТКИ"
            )

            print("=" * 70)

            return False

        print(
            "✅ СТРУКТУРА ФРАНЦУЗСКОЙ ЗАЩИТЫ КОРРЕКТНА"
        )

        print(
            "✅ ВСЕ КОНЕЧНЫЕ ВЕТКИ ДОХОДЯТ ДО 10..."
        )

        print("=" * 70)

        return True


    # Запуск проверки
    if __name__ == "__main__":
        check_opening_book(OPENING_BOOK)
        check_french_structure(OPENING_BOOK)

